mapper.select:
SELECT COUNT(*)
FROM ADMIN_NOTICE N



		AND (
			N.NOTICE_TITLE
				LIKE '%' || #{keyword} || '%'

			OR DBMS_LOB.INSTR(
				N.NOTICE_CONTENT,
				#{keyword}
			) > 0
		)



		AND N.NOTICE_CATEGORY
				= #{category}

mapper.update:
UPDATE ADMIN_NOTICE
SET NOTICE_TITLE = #{noticeTitle},
NOTICE_CONTENT = #{noticeContent},
NOTICE_CATEGORY = #{noticeCategory}
WHERE NOTICE_NUMBER = #{noticeNumber}
